        [2926] = { name = "노가인", objective = "빈 납 채집 약병을 방사능에 오염된 침략자나 약탈자에게 사용한 뒤, 가득 찬 약병을 오지 토글볼트에게 가져가세요." },
        [2962] = { name = "녹색 광채엔 녹색 광채뿐", objective = "고농도 방사능 낙진과 무거운 납 채집 약병을 오지에게 가져가세요. 낙진은 금방 붕괴합니다." },
