        [2904] = { name = "엉망진창", objective = "커노비를 시계태엽 통로 출구까지 호위한 뒤 무법항의 스쿠티에게 보고하세요." },
        [2951] = { name = "반짝반짝 5200!", objective = "때 묻은 물건을 반짝반짝 5200에 넣고 은화 세 개를 넣어 기계를 작동하세요." },
