        [92458] = { name = "擾亂之心", objective = "為達拉然附近的大法師莫德拉的影像取得秘法微粒。", pickup = "大法師莫德拉的影像，達拉然附近的羅德米爾湖", turnin = "大法師莫德拉的影像，達拉然附近的羅德米爾湖" },
