      [4743] = { name = "Le sceau de l'ascension", objective = "Allez à la tourbière du Ver dans le marécage d'Âprefange. Trouvez l'ancien drake, Brandeguerre, et frappez-le sans merci jusqu'à ce que sa volonté soit brisée. A cet instant précis, vous devez placer le Sceau d'ascension brut devant l'énorme bête. Vous devez ensuite utiliser rapidement l'Orbe d'énergie draconique sur sa forme affaiblie et prendre possession de ses facultés mentales. Contrôlez la bête et dirigez les flammes du Vol noir sur le Sceau d'ascension brut !" },
      [4974] = { name = "Pour la Horde !", objective = "Aller au Pic Blackrock et tuer le Chef de guerre, Rend Blackhand. Prendre sa tête et retourner à Orgrimmar." },
      [5089] = { name = "Ordres du général Drakkisath", objective = "Remettre les Ordres du général Drakkisath au maréchal Maxwell dans les Steppes ardentes." },
      [5102] = { name = "La reddition du général Drakkisath", objective = "Rendez-vous au Pic Blackrock et tuez le général Drakkisath, puis retournez voir le maréchal Maxwell." },
      [5127] = { name = "La forge démoniaque", objective = "Se rendre au pic Blackrock et trouver Goraluk Anvilcrack. Le tuer puis utiliser la Pique tachée de sang sur son cadavre. Après avoir siphonné son âme, la pique sera devenue Tachée d'âme. Trouver aussi la Cuirasse couverte de runes inachevée. Rapporter la Pique tachée d'âme et la Cuirasse couverte de runes inachevée à Lorax au Berceau-de-l'Hiver." },
      [6502] = { name = "Amulette drakefeu", objective = "Récupérer le Sang du Champion des dragons noirs sur le général Drakkisath. Il se trouve dans sa salle du trône, derrière les Halls d'Ascension, sur le Pic Blackrock." },
      [6602] = { name = "Le sang du champion des dragons noirs", objective = "Aller au Pic Blackrock, et tuer le général Drakkisath. Récupérer son sang et retourner voir Rexxar." },
      [7761] = { name = "Les ordres de Blackhand", objective = "Cet orc est stupide. Il semble que vous deviez trouver un moyen d’obtenir la Marque de Drakkisath pour accéder à l’Orbe de commandement. D’après la lettre, la Marque est gardée par le général Drakkisath. Vous devriez peut-être enquêter." },
    },
  },
  esES = {
    dungeon = "Cumbre de Roca Negra Superior", location = "Montaña Roca Negra",
    bosses = { ["Pyroguard Emberseer"] = "Piroguardián brasadivino", ["Solakar Flamewreath"] = "Solakar Corona de Fuego", ["Jed Runewatcher"] = "Jed Observarrunas", ["Goraluk Anvilcrack"] = "Goraluk Yunquegrieta", ["Gyth"] = "Gyth", ["Warchief Rend Blackhand"] = "Jefe de Guerra Desgarro Puño Negro", ["The Beast"] = "La Bestia", ["Lord Valthalak"] = "Lord Valthalak", ["General Drakkisath"] = "General Drakkisath" },
    quests = {
      [4734] = { name = "Un huevo congelado", objective = "Usa el prototipo de ovosciloscopio sobre un huevo de El Grajero." },
      [4735] = { name = "La colecta de huevos", objective = "Llévale 8 huevos de dragón y el módulo colectrónico a Tinkee Vaporino en el Peñacho Llamarada, en Las Estepas Ardientes." },
      [4743] = { name = "El Sello de Ascensión", objective = "Viaja a la Ciénaga de Fuego en Marjal Revolcafango. Encuentra al anciano draco Brasaliza y derrótalo sin contemplaciones hasta doblegar su voluntad. Este es el preciso momento en el que debes colocar el Sello de ascensión sin forjar ante la colosal bestia. Debes entonces ser rápido en usar el orbe de energía dracónica sobre su debilitada forma y reclamar el dominio sobre sus facultades mentales. ¡Controla la bestia y dirige las llamas del Vuelo Negro sobre el Sello de ascensión sin forjar!" },
      [4974] = { name = "¡Por la Horda!", objective = "Ve a Cumbre de Roca Negra para matar al Jefe de Guerra Rend Puño Negro. Llévale su cabeza a Orgrimmar." },
      [5089] = { name = "Orden del general Drakkisath", objective = "Llévale la orden del general Drakkisath al alguacil Maxwell en Las Estepas Ardientes." },
      [5102] = { name = "Muerte al general Drakkisath", objective = "Viaja hasta la Cumbre de Roca Negra y mata al general Drakkisath. Vuelve junto al alguacil Maxwell cuando hayas acabado tu trabajo." },
      [5127] = { name = "La forja demoníaca", objective = "Viaja a la Cumbre de Roca Negra y encuentra a Goraluk Yunquegrieta. Mátale y utiliza el Pico manchado de sangre sobre su cadáver. Cuando hayas absorbido su alma, el pico estará manchado de alma. También debes encontrar el peto cubierto de runas sin forjar. Lleva el pico manchado de alma y el peto cubierto de runas sin forjar a Lorax en Cuna del Invierno." },
      [6502] = { name = "Amuleto Pirodraco", objective = "Tienes que recuperar la sangre de dragón negro campeón, la tiene el general Drakkisath. Puedes encontrar a Drakkisath en su sala del trono, tras las Salas de la Ascensión, en la Cumbre de Roca Negra." },
      [6602] = { name = "La sangre de dragón negro campeón", objective = "Viaja a la Cumbre de Roca Negra y mata al general Drakkisath. Recoge su sangre y llévasela a Rexxar." },
      [7761] = { name = "La orden de Puño Negro", objective = "¡Será estúpido ese orco! Al parecer, tienes que encontrar esta señal y ganar la marca de Drakkisath para poder acceder al orbe de orden. Según la carta, el general Drakkisath guarda la señal. Quizás deberías investigarlo." },
    },
  },
  itIT = {
    dungeon = "Guglia di Roccianera Superiore", location = false,
    bosses = { },
  },
  ptBR = {
    dungeon = "Pico da Rocha Negra Superior", location = "Montanha Rocha Negra",
    bosses = { ["Pyroguard Emberseer"] = "Piroguarda Mirabrasa", ["Solakar Flamewreath"] = "Solakar Chamarco", ["Jed Runewatcher"] = "Jed Mirarruna", ["Goraluk Anvilcrack"] = "Goraluk Rachadastra", ["Gyth"] = "Gyth", ["Warchief Rend Blackhand"] = "Chefe Guerreiro Laceral Mão Negra", ["The Beast"] = "A Fera", ["Lord Valthalak"] = "Lorde Valthalak", ["General Drakkisath"] = "General Drakkisath" },
    quests = {
      [4734] = { name = "Congelar os ovos", objective = "Use o Protótipo de Ovosciloscópio em um ovo no Viveiro." },
      [4735] = { name = "Coleção de ovos", objective = "Leve 8 Ovos de Dragão Recolhidos e o Módulo Colectrônico a Vera Brequim no Monte Candente, que fica nas Estepes Ardentes." },
      [4743] = { name = "Selo da Ascensão", objective = "Vá para o Pântano da Serpe, que fica no Pântano Vadeoso. Encontre o draco ancião Ardeluta e ataque-o sem misericórdia até que sua vontade seja quebrada. É nesse momento que você deve colocar o Selo da Ascensão de Metal Bruto em frente a essa fera imponente. Você deve então ser rápido para usar o Orbe de Energia Dracônica em sua forma enfraquecida e dominar suas faculdades mentais. Controle a fera e lance as chamas da Revoada Dragônica Negra sobre o Selo da Ascensão de Metal Bruto!" },
      [4974] = { name = "Pela Horda!", objective = "Viaje para o Pico da Rocha Negra e mate o Chefe Guerreiro Laceral Mão Negra. Pegue sua cabeça e volte para Orgrimmar." },
      [5089] = { name = "Comando do General Drakkisath", objective = "Leve o Comando do General Drakkisath para o Oficial Maxwell nas Estepes Ardentes." },
      [5102] = { name = "O fim do General Drakkisath", objective = "Viaje de volta ao Pico da Rocha Negra e destrua o General Drakkisath. Depois, fale novamente com o Oficial Maxwell." },
      [5127] = { name = "A forja demoníaca", objective = "Viaje para o Pico da Rocha Negra e encontre Goraluk Rachadastra. Mate-o e use o Pique Manchado de Sangue no cadáver dele. Quando a alma dele tiver sido canalizada, o pique ficará Manchado de Almas. Você também precisa encontrar o Peitoral Rúnico de Metal Bruto. Leve o Pique Manchado de Almas e o Peitoral Rúnico de Metal Bruto para Vegax, em Hibérnia." },
      [6502] = { name = "Amuleto da Chama Dracônica", objective = "Confronte o General Drakkisath e consiga o Sangue do Campeão dos Dragões Negros. Drakkisath está na sala do trono atrás dos Salões da Ascensão, no Pico da Rocha Negra." },
      [6602] = { name = "Sangue do Campeão dos Dragões Negros", objective = "Viaje para o Pico da Rocha Negra e mate o General Drakkisath. Recolha seu sangue e leve-o para Rexxar." },
      [7761] = { name = "Comando do Mão Negra", objective = "Sem dúvida, um orc excepcionalmente burro. Parece que para acessar o Orbe de Comando é necessário ter a Marca de Drakkisath. A carta indica que o próprio General Drakkisath a guarda. Talvez você devesse investigar." },
    },
  },
  ruRU = {
    dungeon = "Верхняя часть пика Черной горы", location = "Черная гора",
    bosses = { ["Pyroguard Emberseer"] = "Пиростраж Созерцатель Углей", ["Solakar Flamewreath"] = "Солакарский огнечервь", ["Jed Runewatcher"] = "Джед Руновед", ["Goraluk Anvilcrack"] = "Горалук Треснувшая Наковальня", ["Gyth"] = "Гит", ["Warchief Rend Blackhand"] = "Вождь Ренд Чернорук", ["The Beast"] = "Зверь", ["Lord Valthalak"] = "Лорд Вальтхалак", ["General Drakkisath"] = "Генерал Драккисат" },
    quests = {
      [4734] = { name = "Заморозка яйца", objective = "Испытайте прототип яйцехладоскопа на одном из яиц в Гнездовье." },
      [4735] = { name = "Сбор яиц", objective = "Принесите 8 драконьих яиц и устройство-коллекционер Тинки Кипеллер в Пламенеющий Стяг в Пылающих степях." },
      [4743] = { name = "Печать Вознесения", objective = "Идите в Драконьи топи в Пылевых топях. Найдите Огнебора и бейте его, не жалея, чтобы сломить его волю. Как только воля великого зверя ослабнет, надо немедленно положить перед ним заготовку печати Вознесения и воспользоваться сферой Энергии дракона, чтобы подчинить себе его разум и направить его пламя на заготовку." },
      [4974] = { name = "За Орду!", objective = "Пойдите в Пик Черной горы и убейте вождя Ренда Чернорука. Принесите его голову в Оргриммар." },
      [5089] = { name = "Приказ генерала Драккисата", objective = "Отнесите приказ генерала Драккисата маршалу Максвеллу в Пылающие степи." },
      [5102] = { name = "Кончина генерала Драккисата", objective = "Отправьтесь на пик Черной горы и устраните генерала Драккисата. По выполнении задания вернитесь к маршалу Максвеллу." },
      [5127] = { name = "Демонова кузня", objective = "Отправляйтесь на пик Черной горы и найдите Горалука Треснувшую Наковальню. Убейте его, а потом воткните в труп окровавленную пику. Таким образом пика вытянет его душу и окрасится ей. Кроме того, вам нужно найти заготовку рунической кирасы. Отнесите пику и кирасу Лораксу в Зимних Ключах." },
      [6502] = { name = "Амулет Пламени дракона", objective = "Добудьте кровь могучего черного дракона генерала Драккисата, которого можно найти сидящим на троне в залах Вознесения в Пике Черной горы." },
      [6602] = { name = "Кровь могучего черного дракона", objective = "Отправляйтесь к пику Черной горы и убейте генерала Драккисата. Соберите его кровь и вернитесь к Рокаро." },
      [7761] = { name = "Приказ Чернорука", objective = "Вот уж действительно идиот... Похоже, вам нужно найти это клеймо и выжечь на руке метку Драккисата, чтобы получить доступ к сфере Приказа. В письме ясно сказано, что генерал Драккисат охраняет клеймо. Наверное, стоит проверить." },
    },
  },
  koKR = {
    dungeon = "검은바위 첨탑 상층", location = "검은바위 산",
    bosses = { ["Pyroguard Emberseer"] = "불의수호자 엠버시어", ["Solakar Flamewreath"] = "화염고리 솔라카르", ["Jed Runewatcher"] = "제드 룬와처", ["Goraluk Anvilcrack"] = "고랄루크 앤빌크랙", ["Gyth"] = "기스", ["Warchief Rend Blackhand"] = "대족장 렌드 블랙핸드", ["The Beast"] = "괴수", ["Lord Valthalak"] = "군주 발타라크", ["General Drakkisath"] = "사령관 드라키사스" },
    quests = {
      [4734] = { name = "알껍질 냉동", objective = "알껍질급속냉각기 견본을 둥지에 있는 알에 사용해야 합니다." },
      [4735] = { name = "알 수집", objective = "불타는 평원의 화염 마루에 있는 팅키 스팀보일에게 수집한 용의 알 8개를 가져가야 합니다." },
      [4743] = { name = "승천의 인장", objective = "먼지진흙 습지대에 있는 용의 둥지로 가서 고대 비룡, 엠버스트라이프를 찾아 그의 의지가 꺾일 때까지 무자비하게 공격을 펼쳐야 합니다. 바로 그때 거대한 엠버스트라이프 앞에 벼려지지 않은 승천의 인장을 가져다 놓으십시오. 그리고 약해진 엠버스트라이프에게 재빨리 용력의 보주를 사용해 그의 정신력을 조종해야 합니다. 엠버스트라이프를 조종해 검은용군단의 화염을 벼려지지 않은 승천의 인장에 뿜어야 합니다!" },
      [4974] = { name = "호드를 위하여!", objective = "검은바위 첨탑으로 가서 대족장 렌드 블랙핸드를 처치하십시오. 그 증거로 그의 머리카락을 가지고 오그리마로 돌아와야 합니다." },
      [5089] = { name = "사령관 드라키사스의 명령서", objective = "불타는 평원에 있는 치안대장 맥스웰에게 사령관 드라키사스의 명령서를 가져가야 합니다." },
      [5102] = { name = "사령관 드라키사스 처치", objective = "검은바위 첨탑으로 가서 사령관 드라키사스를 처치해야 합니다. 임무를 완수하면 치안대장 맥스웰에게 돌아가야 합니다." },
      [5127] = { name = "악마의 룬", objective = "검은바위 첨탑으로 가서 고랄루크 앤빌크랙을 찾아 처치한 후, 핏물이 깃든 창을 그의 심장에 꽂으십시오. 창이 그의 영혼을 흡수하면 영혼이 깃든 창으로 변합니다. 벼려지지 않은 룬문자 흉갑도 찾아야 합니다. 영혼이 깃든 창과 벼려지지 않은 룬문자 흉갑을 여명의 설원에 있는 로락스에게 갖다주십시오." },
      [6502] = { name = "비룡불꽃 아뮬렛", objective = "사령관 드라키사스에게서 검은용 용사의 피를 가져와야 합니다. 드라키사스는 검은바위 첨탑의 승천의 전당 뒤에 있는 알현실에 있습니다." },
      [6602] = { name = "검은용 용사의 피", objective = "검은바위 첨탑으로 가서 사령관 드라키사스를 처치하고 사령관의 피를 모아 렉사르에게 가져가야 합니다." },
      [7761] = { name = "블랙핸드의 명령서", objective = "아주 멍청한 오크로군요. 지배의 보주를 사용하려면 드라키사스의 낙인을 찾아 드라키사스의 징표를 받아야 할 거 같습니다. 이 편지에 따르면 드라키사스 사령관이 낙인을 지키고 있다고 하니 조사해 보는 것이 좋겠습니다." },
    },
  },
  zhCN = {
    dungeon = "黑石塔上层", location = "黑石山",
    bosses = { ["Pyroguard Emberseer"] = "烈焰卫士艾博希尔", ["Solakar Flamewreath"] = "索拉卡·火冠", ["Jed Runewatcher"] = "杰德", ["Goraluk Anvilcrack"] = "古拉鲁克", ["Gyth"] = "盖斯", ["Warchief Rend Blackhand"] = "大酋长雷德·黑手", ["The Beast"] = "比斯巨兽", ["Lord Valthalak"] = "瓦塔拉克公爵", ["General Drakkisath"] = "达基萨斯将军" },
    quests = {
      [4734] = { name = "冷冻龙蛋", objective = "在孵化间对着某颗龙蛋使用龙蛋冷冻器初号机。" },
      [4735] = { name = "收集龙蛋", objective = "将电动采集模块和8颗收集到的龙蛋交给燃烧平原烈焰峰的丁奇·斯迪波尔。" },
      [4743] = { name = "晋升印章", objective = "到尘泥沼泽中的巨龙沼泽去。找到上古老龙埃博斯塔夫，对他发起无情的攻击，直到他的意志被摧毁。此时，你必须尽快将未铸造的晋升印章放在这条龙面前，并使用龙力宝珠控制他的躯体，强迫他将黑龙的烈焰喷向未铸造的晋升印章！" },
      [4974] = { name = "为部落而战！", objective = "去黑石塔杀死大酋长雷德·黑手，带着他的头颅返回奥格瑞玛。" },
      [5089] = { name = "达基萨斯将军的命令", objective = "把达基萨斯将军的命令交给燃烧平原的麦克斯韦尔元帅。" },
      [5102] = { name = "达基萨斯将军之死", objective = "到黑石塔去杀掉达基萨斯将军，完成任务之后就回到麦克斯韦尔元帅那里复命。" },
      [5127] = { name = "恶魔熔炉", objective = "到黑石塔去找到古拉鲁克。杀死他，然后用血污长矛刺入他的尸体。当他的灵魂被吸干后，这支矛就会成为穿魂长矛。你还必须找到未铸造的符文覆饰胸甲。将穿魂长矛和未铸造的符文覆饰胸甲都交给冬泉谷的罗拉克斯。" },
      [6502] = { name = "龙火护符", objective = "你必须从达基萨斯将军身上取回黑龙勇士之血，你可以在黑石塔的晋升大厅后面的房间里找到他。" },
      [6602] = { name = "黑龙勇士之血", objective = "到黑石塔去杀掉达基萨斯将军，把它的血交给雷克萨。" },
      [7761] = { name = "黑手的命令", objective = "真是个愚蠢的兽人。看来你需要找到那枚烙印并获得达基萨斯徽记才可以使用命令宝珠。你从信中获知，达基萨斯将军守卫着烙印。也许你应该就此进行更深入的调查。" },
    },
  },
  zhTW = {
    dungeon = "黑石塔上層", location = "黑石山",
    bosses = { ["Pyroguard Emberseer"] = "烈焰衛士艾博希爾", ["Solakar Flamewreath"] = "索拉卡·火冠", ["Jed Runewatcher"] = "傑德", ["Goraluk Anvilcrack"] = "古拉魯克", ["Gyth"] = "蓋斯", ["Warchief Rend Blackhand"] = "大酋長雷德·黑手", ["The Beast"] = "比斯巨獸", ["Lord Valthalak"] = "瓦塔拉克公爵", ["General Drakkisath"] = "達基薩斯將軍" },
    quests = {
      [4734] = { name = "冷凍龍蛋", objective = "在孵化間對著某顆龍蛋使用龍蛋冷凍器初號機。" },
      [4735] = { name = "收集龍蛋", objective = "將電動採集模組和8顆收集到的龍蛋交給燃燒平原烈焰峰的丁奇·斯迪波爾。" },
      [4743] = { name = "晉升印章", objective = "到塵泥沼澤中的巨龍沼澤去。找到上古老龍埃博斯塔夫，對他發起無情的攻擊，直到他的意志被摧毀。此時，你必須儘快將未鑄造的晉升印章放在這條龍面前，並使用龍力寶珠控制他的軀體，強迫他將黑龍的烈焰噴向未鑄造的晉升印章！" },
      [4974] = { name = "為部落而戰！", objective = "去黑石塔殺死大酋長雷德·黑手，帶著他的頭顱返回奧格瑞瑪。" },
      [5089] = { name = "達基薩斯將軍的命令", objective = "把達基薩斯將軍的命令交給燃燒平原的麥克斯韋爾元帥。" },
      [5102] = { name = "達基薩斯將軍之死", objective = "到黑石塔去殺掉達基薩斯將軍，完成任務之後就回到麥克斯韋爾元帥那裡覆命。" },
      [5127] = { name = "惡魔熔爐", objective = "到黑石塔去找到古拉魯克。殺死他，然後用血汙長矛刺入他的屍體。當他的靈魂被吸乾後，這支矛就會成為穿魂長矛。你還必須找到未鑄造的符文覆飾胸甲。將穿魂長矛和未鑄造的符文覆飾胸甲都交給冬泉谷的羅拉克斯。" },
      [6502] = { name = "龍火護符", objective = "你必須從達基薩斯將軍身上取回黑龍勇士之血，你可以在黑石塔的晉升大廳後面的房間裡找到他。" },
      [6602] = { name = "黑龍勇士之血", objective = "到黑石塔去殺掉達基薩斯將軍，把它的血交給雷克薩。" },
      [7761] = { name = "黑手的命令", objective = "真是個愚蠢的獸人。看來你需要找到那枚烙印並獲得達基薩斯徽記才可以使用命令寶珠。你從信中獲知，達基薩斯將軍守衛著烙印。也許你應該就此進行更深入的調查。" },
    },
  },
}
for lang, data in pairs(UBRS_LOC) do
    local content = FDJ.ContentLocales[lang] or {}
    FDJ.ContentLocales[lang] = content
    content.dungeons = content.dungeons or {}
    content.bosses = content.bosses or {}
    content.places = content.places or {}
    content.quests = content.quests or {}
    if content.dungeons["Upper Blackrock Spire"] == nil then
        content.dungeons["Upper Blackrock Spire"] = { name = data.dungeon, location = data.location or nil }
    end
    for english, localName in pairs(data.bosses or {}) do
        if content.bosses[english] == nil then content.bosses[english] = localName end
        if content.places[english] == nil then content.places[english] = localName end
    end
    for id, entry in pairs(data.quests or {}) do
        if content.quests[id] == nil then content.quests[id] = entry end
    end
end

